<x-employer-dashboard-layout title="Purchase details" active="purchases" subtitle="Payment status is confirmed by the server, not by browser checkout alone.">
    <div class="mx-auto max-w-3xl space-y-5"><a class="text-sm font-semibold text-brand-700 hover:underline" href="{{ route('employer.purchases.index') }}">← Billing history</a><section class="rounded-2xl border border-slate-200 bg-white p-6"><div class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-wider text-slate-500">Purchase reference</p><p class="mt-1 font-mono text-sm">{{ $purchase->purchase_reference }}</p><h2 class="mt-4 text-xl font-extrabold">{{ $purchase->package_snapshot['name'] ?? 'Package' }}</h2></div><x-ui.badge>{{ ucfirst($purchase->status->value) }}</x-ui.badge></div><div class="mt-5 grid gap-4 border-t border-slate-100 pt-5 sm:grid-cols-3"><div><p class="text-xs text-slate-500">Amount</p><p class="mt-1 font-bold">{{ $purchase->formattedAmount() }} {{ $purchase->currency }}</p></div><div><p class="text-xs text-slate-500">Purchased</p><p class="mt-1 font-bold">{{ $purchase->created_at?->format('M j, Y H:i') }}</p></div><div><p class="text-xs text-slate-500">Entitlement</p><p class="mt-1 font-bold">{{ $purchase->entitlement ? $purchase->entitlement->credits_remaining.' credits available' : 'Not granted' }}</p></div></div>@if($payment?->failure_code)<p class="mt-5 rounded-xl bg-amber-50 p-4 text-sm text-amber-950">The last attempt did not complete: {{ str_replace('_', ' ', $payment->failure_code) }}. No package credit has been granted.</p>@endif
        @if($purchase->status->value === 'pending' && $checkoutReady && $payment?->provider_order_id && $payment->status->value === 'created')<div class="mt-6 rounded-xl bg-slate-50 p-4"><p class="text-sm text-slate-600">Continue with Razorpay. Access will remain pending until server verification confirms a matching captured payment.</p><button id="razorpay-checkout" type="button" class="mt-4 rounded-xl bg-brand-700 px-5 py-3 text-sm font-bold text-white hover:bg-brand-800">Pay {{ $purchase->formattedAmount() }}</button><p id="checkout-status" class="mt-3 text-sm text-slate-600" role="status"></p></div>
            <form id="verify-form" method="POST" action="{{ route('employer.purchases.verify', $purchase) }}" class="hidden">@csrf<input name="razorpay_order_id"><input name="razorpay_payment_id"><input name="razorpay_signature"></form>
            <script src="https://checkout.razorpay.com/v1/checkout.js"></script><script>
                document.getElementById('razorpay-checkout')?.addEventListener('click', () => {
                    const checkout = new Razorpay({key: @js($razorpayKeyId), amount: @js($payment->amount_paise), currency: @js($payment->currency), name: @js(config('app.name')), description: @js($purchase->package_snapshot['name'] ?? 'Package'), order_id: @js($payment->provider_order_id), handler: response => {
                        const form = document.getElementById('verify-form');
                        for (const field of ['razorpay_order_id', 'razorpay_payment_id', 'razorpay_signature']) form.elements[field].value = response[field];
                        document.getElementById('checkout-status').textContent = 'Verifying payment with Razorpay…';
                        form.submit();
                    }, modal: {ondismiss: () => {document.getElementById('checkout-status').textContent = 'Checkout closed. The purchase is still pending until payment is verified.';}}});
                    checkout.on('payment.failed', () => {document.getElementById('checkout-status').textContent = 'Razorpay reported a failed attempt. No entitlement has been granted.';});
                    checkout.open();
                });
            </script>
        @elseif(in_array($purchase->status->value, ['pending', 'failed'], true) && $checkoutReady)<form method="POST" action="{{ route('employer.purchases.retry', $purchase) }}" class="mt-5">@csrf<button class="rounded-xl bg-brand-700 px-5 py-3 text-sm font-bold text-white hover:bg-brand-800">Retry payment</button></form>
        @elseif($purchase->status->value === 'pending' && ! $checkoutReady)<p class="mt-5 rounded-xl bg-amber-50 p-4 text-sm text-amber-950">Checkout is unavailable while package purchases or payment configuration are disabled. Your purchase remains pending.</p>@endif
    </section></div>
</x-employer-dashboard-layout>
